import asyncio
import httpx
from fastmcp.server import FastMCP


async def create_openapi_mcp_server(
    openapi_spec: dict,
    client: httpx.AsyncClient,
    server_name: str = "OpenAPI MCP Server",
) -> FastMCP:
    """Create an MCP server from an OpenAPI specification.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a dictionary
        client: Configured httpx.AsyncClient with base URL set
        server_name: Name for the MCP server

    Returns:
        FastMCP server with tools mirroring the OpenAPI operations
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=server_name,
    )


async def main():
    # Example: minimal OpenAPI 3.0 specification
    openapi_spec = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "servers": [{"url": "https://api.example.com"}],
        "paths": {
            "/users": {
                "get": {
                    "operationId": "listUsers",
                    "summary": "List all users",
                    "responses": {
                        "200": {
                            "description": "List of users",
                            "content": {
                                "application/json": {
                                    "schema": {
                                        "type": "array",
                                        "items": {
                                            "type": "object",
                                            "properties": {
                                                "id": {"type": "integer"},
                                                "name": {"type": "string"},
                                            },
                                        },
                                    }
                                }
                            },
                        }
                    },
                }
            }
        },
    }

    # Create httpx.AsyncClient configured with the API base URL
    async with httpx.AsyncClient(
        base_url="https://api.example.com",
        timeout=30.0,
    ) as client:
        # Create MCP server from OpenAPI spec
        server = await create_openapi_mcp_server(openapi_spec, client)

        # Run the server
        await server.run_stdio_async()


if __name__ == "__main__":
    asyncio.run(main())

